<?php
namespace App\Http\Controllers;use App\Contracts\EmailValidatorInterface;use App\Http\Requests\BatchRequest;use App\Http\Requests\ValidateEmailRequest;use Illuminate\Http\JsonResponse;
final readonly class ValidationController {public function __construct(private EmailValidatorInterface $validator){}public function single(ValidateEmailRequest $request):JsonResponse{$d=$request->validated();$result=$this->one($d['email'],$d);return response()->json(['ok'=>true,'data'=>$result]);}public function batch(BatchRequest $request):JsonResponse{$d=$request->validated();$results=array_map(fn(string $e):array=>$this->one($e,$d),$d['emails']);return response()->json(['ok'=>true,'data'=>['results'=>$results,'summary'=>$this->summary($results)]]);}public function one(string $email,array $options=[]):array{return $this->validator->validate($email,$options['disposable_domains']??config('validation_v2.disposable_domains'),$options['role_based_prefixes']??config('validation_v2.role_prefixes'),(bool)($options['enable_company_lookup']??true));}private function summary(array $results):array{$v=[];foreach($results as$r)$v[$r['Verdict']]=($v[$r['Verdict']]??0)+1;return ['total'=>count($results),'verdicts'=>$v];}}
